Translate the following GNU C++14 code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++14 code you have to translate:
<original_code>
#include <cmath>
#include <iostream>
#include <memory>
using namespace std;

int gcd(int a, int b) {
    if (b == 0) return a;
    return gcd(b, a % b);
}

int main() {
    int x, y, n;
    cin >> x >> y >> n;

    int g = gcd(x, y);
    x /= g;
    y /= g;

    if (n >= y) {
        cout << x << "/" << y << "\n";
        return 0;
    }

    long double target = (long double)x / y;
    long double bestError = target;
    unique_ptr<int[]> ans(new int[n]());
    int bestDen = 1;

    for (int i = 1; i <= n; ++i) {
        long double h = i * target;
        long double low = floor(h);
        long double errLow = std::fabs(low / i - target);
        long double errHigh = std::fabs((low + 1) / i - target);

        if (bestError > errLow || bestError > errHigh) {
            if (errLow > errHigh) {
                ans[i - 1] = static_cast<int>(low) + 1;
                bestDen = i;
                bestError = errHigh;
            } else {
                ans[i - 1] = static_cast<int>(low);
                bestDen = i;
                bestError = errLow;
            }
        }
    }

    cout << ans[bestDen - 1] << "/" << bestDen;
    return 0;
}
